-- Hand-translated Supabase A triggers (see supabase-schema-a.json). Timestamps use the
-- Postgres JSON shape (+00:00) so text ordering matches copied rows.
CREATE TABLE IF NOT EXISTS d1_native_sql_errors(message TEXT);
CREATE TRIGGER IF NOT EXISTS "a_public__email_campaign_recipients_updated_at" AFTER UPDATE ON "a_public__email_campaign_recipients" FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at OR 1 BEGIN UPDATE "a_public__email_campaign_recipients" SET updated_at=strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE rowid=NEW.rowid; END;
CREATE TRIGGER IF NOT EXISTS "a_public__email_campaigns_updated_at" AFTER UPDATE ON "a_public__email_campaigns" FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at OR 1 BEGIN UPDATE "a_public__email_campaigns" SET updated_at=strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE rowid=NEW.rowid; END;
CREATE TRIGGER IF NOT EXISTS "a_public__email_contacts_updated_at" AFTER UPDATE ON "a_public__email_contacts" FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at OR 1 BEGIN UPDATE "a_public__email_contacts" SET updated_at=strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE rowid=NEW.rowid; END;
CREATE TRIGGER IF NOT EXISTS "a_public__lesson_tasks_touch_updated_at" AFTER UPDATE ON "a_public__lesson_tasks" FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at OR 1 BEGIN UPDATE "a_public__lesson_tasks" SET updated_at=strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE rowid=NEW.rowid; END;
CREATE TRIGGER IF NOT EXISTS "a_public__student_lesson_task_progress_touch_updated_at" AFTER UPDATE ON "a_public__student_lesson_task_progress" FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at OR 1 BEGIN UPDATE "a_public__student_lesson_task_progress" SET updated_at=strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE rowid=NEW.rowid; END;
CREATE TRIGGER IF NOT EXISTS "a_crm_v2__trg_prevent_published_workflow_version_update" BEFORE UPDATE ON "a_crm_v2__workflow_versions" FOR EACH ROW WHEN OLD.status='published' BEGIN SELECT RAISE(ABORT,'Published workflow versions are immutable'); END;
CREATE TRIGGER IF NOT EXISTS "a_crm_v2__trg_prevent_published_workflow_version_delete" BEFORE DELETE ON "a_crm_v2__workflow_versions" FOR EACH ROW WHEN OLD.status='published' BEGIN SELECT RAISE(ABORT,'Published workflow versions are immutable'); END;
CREATE TRIGGER IF NOT EXISTS "a_public__payment_remarketing_runs_after_order_insert" AFTER INSERT ON "a_public__orders" FOR EACH ROW WHEN NEW.status='pending' AND trim(coalesce(NEW.email,''))<>'' BEGIN INSERT INTO "a_public__payment_remarketing_runs"(id,order_id,sequence_index,product_key,due_at,status,attempt_count,created_at,updated_at) VALUES(lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6))),NEW.id,1,'pending_order',strftime('%Y-%m-%dT%H:%M:%S+00:00', date(datetime(NEW.created_at,'+7 hours'), CASE WHEN time(datetime(NEW.created_at,'+7 hours'))<'08:30:00' THEN '+0 days' ELSE '+1 days' END) || ' 08:30:00','-7 hours'),'queued',0,strftime('%Y-%m-%dT%H:%M:%f+00:00','now'),strftime('%Y-%m-%dT%H:%M:%f+00:00','now')) ON CONFLICT(order_id,sequence_index) DO NOTHING; END;
CREATE TRIGGER IF NOT EXISTS "a_public__payment_remarketing_runs_after_order_status_update" AFTER UPDATE OF status,payment_status ON "a_public__orders" FOR EACH ROW WHEN (OLD.status IS NOT NEW.status OR OLD.payment_status IS NOT NEW.payment_status) AND (NEW.status NOT IN ('pending','expired') OR NEW.payment_status='paid') BEGIN UPDATE "a_public__payment_remarketing_runs" SET status='cancelled',lease_token=NULL,lease_expires_at=NULL,next_attempt_at=NULL,last_error='Order is no longer unpaid',updated_at=strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE order_id=NEW.id AND status IN ('queued','retry','sending'); END;
CREATE TRIGGER IF NOT EXISTS "a_public__payment_remarketing_engagement_after_email_log" AFTER UPDATE OF opened_at,clicked_at ON "a_public__email_logs" FOR EACH ROW WHEN NEW.resend_email_id IS NOT NULL AND (NEW.opened_at IS NOT NULL OR NEW.clicked_at IS NOT NULL) BEGIN UPDATE "a_public__payment_remarketing_runs" SET opened_at=coalesce(opened_at,NEW.opened_at),clicked_at=coalesce(clicked_at,NEW.clicked_at),updated_at=strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE resend_email_id=NEW.resend_email_id; END;
